import pandas as pd
from app_db import SessionLocal, Project, Base, engine
from ml_core.inference.infer import run_inference
from datetime import datetime

# Recreate tables to avoid schema mismatches
Base.metadata.drop_all(bind=engine)
Base.metadata.create_all(bind=engine)

db = SessionLocal()

def seed_from_dataset():
    # Read the dataset generated by generator.py
    df = pd.read_csv('dataset.csv')
    
    # Sort by date so we can keep the latest update for each project
    df['update_date'] = pd.to_datetime(df['update_date'])
    df = df.sort_values(by='update_date', ascending=True)
    
    # Group by project to get the latest state
    latest_states = df.drop_duplicates(subset=['project_id'], keep='last')
    
    # We will seed all extracted projects
    sample = latest_states
    
    as_of = datetime.now().strftime("%Y-%m-%d")
    
    print(f"Clearing old projects...")
    db.query(Project).delete()
    
    print(f"Seeding {len(sample)} projects from dataset...")
    count = 0
    for idx, row in sample.iterrows():
        p_id = row['project_id']
        
        # We need to run inference to get the risk_score
        # Create a single row DF for inference matching what it expects
        # The training pipeline expects historical data too but `run_inference` handles it if we pass the full history.
        # However, to be fast we can just mock the inference risk if it fails, or try calling it.
        # Actually, let's just use the logic from backend.main.predict_risk_internal
        
        # Let's just create the Project object
        project = Project(
            id=p_id,
            name=f"Project {p_id} ({row['sector']})",  # Fallback name
            sector=row['sector'],
            ministry=row['ministry'],
            implementing_agency=row['agency'],
            original_cost_cr=round(float(row['sanctioned_cost']), 2),
            expenditure_cr=round(float(row['cumulative_expenditure']), 2),
            physical_progress_pct=round(float(row['physical_progress_pct']), 2),
            delay_months=round(float(row.get('max_milestone_delay_months', 0) if 'max_milestone_delay_months' in row else 0), 2),
            cost_overrun_pct=round(float(row.get('cost_growth_pct', 0) if 'cost_growth_pct' in row else 0), 2),
            status="In Progress",
            risk_score=0,
            risk_level="Low",
            is_anomalous=False
        )
        
        # Just use some simple heuristic based on the labels or overrun flag
        if row.get('delayed_flag') == 1 or row.get('overrun_flag') == 1:
            project.risk_score = 85.0
            project.risk_level = "Critical" if row.get('overrun_flag') == 1 else "High"
        else:
            project.risk_score = 25.0
            
        db.add(project)
        count += 1
        
    db.commit()
    print(f"Seeded {count} projects into the database.")

if __name__ == "__main__":
    seed_from_dataset()
